                K(gi,     gj)     += kt(2*i,   2*j);
                K(gi,     gj + 1) += kt(2*i,   2*j + 1);
                K(gi + 1, gj)     += kt(2*i+1, 2*j);
                K(gi + 1, gj + 1) += kt(2*i+1, 2*j + 1);
            }
        }
    }

    // Emit as JSON
    std::cout << std::setprecision(6) << std::scientific;
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 8; ++i) {
        std::cout << "[";
        for (int j = 0; j < 8; ++j) {
            std::cout << K(i, j);
            if (j < 7) std::cout << ",";
        }
        std::cout << "]";
        if (i < 7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
